'use strict';
/**
 * Browser bundle for the v3 engine, built at runtime by the server. No bundler, no build step.
 *
 * WHAT THIS IS FOR
 * The site used to run `src/core/ai-core.js` in the browser via `/js/ai-core.js`, then
 * `quoridor-engine/engines/v1`. It now runs the real `quoridor-engine/engines/v3`, the same one the
 * server-side bots and the arena use. The generated file keeps the historical `/js/ai-v1.js` URL and
 * the `AiV1` global; `createEngineV1` is an alias for `createEngineV3` so the worker and the demo
 * board do not care which engine is behind the name.
 *
 * The engine is CommonJS and depends on two modules:
 *   require('../../rules')       -> the canonical rules, which the browser already has as the global
 *                                   `Shared` from /shared.js. Rules are NEVER duplicated here. The
 *                                   engine catches a failing require, so the bundle itself refuses to
 *                                   build an engine without the rules global (loud, load-time error).
 *   require('../../tools/rng')   -> pure JS with no Node API, so its source is embedded verbatim.
 *
 * The whole thing is wrapped in a three-line module registry. That is not a bundler: there is no
 * dependency graph walk, no transpilation and no duplicated code, just the two source files and a
 * `require` that resolves to `Shared` for the rules.
 *
 * STRICT MODE
 * The wrapper IIFE is strict, so the embedded `'use strict'` at the top of each source file being
 * preceded by the injected `require` shim does not cost us anything: everything nested inside a
 * strict function is strict regardless of directive position.
 *
 * CACHING
 * The result is cached in memory. Changing the engine therefore requires a server restart, which is
 * also what deploys do. Browsers additionally need the `?v=` bump in frontend/index.html.
 */

const fs = require('fs');
const path = require('path');

const ENGINE_DIR = path.join(__dirname, '..', '..', 'quoridor-engine');
const RNG_FILE = path.join(ENGINE_DIR, 'tools', 'rng.js');
const ENGINE_FILE = path.join(ENGINE_DIR, 'engines', 'v3', 'index.js');
const PERSONALITY_FILE = path.join(ENGINE_DIR, 'engines', 'personality.js');

/**
 * The four bot tiers: search depth per label. The tiers use the same full eval (no eval profile, no
 * random moves), so a weaker tier is just a shallower search of the exact same engine.
 *
 * easy d4 -> hard d8 are depth-capped and finish well inside their DIFFICULTY_MS budget; impossible
 * is time-bound on purpose (DIFFICULTY_MS fallback = 1000ms), which is what separates it from hard.
 * Arena round-robin Elo with the full eval: d4 < d6 < d8 << time-bound (no depth inversions).
 */
const DIFFICULTY_DEPTH = { easy: 4, medium: 6, hard: 8, impossible: 56 };

const DEFAULT_MAX_DEPTH = 3;

/**
 * Depth for a difficulty label. Callers pass maxDepth explicitly to the engine, so this is the only
 * place where a label turns into a number.
 */
function difficultyToMaxDepth(difficulty) {
    const d = DIFFICULTY_DEPTH[difficulty];
    return d === undefined ? DEFAULT_MAX_DEPTH : d;
}

let cached = null;

function buildAiV1Bundle() {
    if (cached) return cached;

    // Normalised to LF: the wrapper below is joined with \n, and the working tree is CRLF on Windows.
    const rngSrc = fs.readFileSync(RNG_FILE, 'utf8').replace(/\r\n/g, '\n');
    const engineSrc = fs.readFileSync(ENGINE_FILE, 'utf8').replace(/\r\n/g, '\n');
    const personalitySrc = fs.readFileSync(PERSONALITY_FILE, 'utf8').replace(/\r\n/g, '\n');

    cached = [
        '/* Quoridor AI v3 - generated by src/core/ai-v1-bundle.js. Do not edit by hand. */',
        '(function (global) {',
        '  "use strict";',
        // The engine swallows a failing rules require ("works without it"), which would turn a missing
        // /shared.js into a crash at first think() instead of a loud load-time error.
        '  if (!global.Shared) {',
        '    throw new Error("AI v3: /shared.js must be loaded before /js/ai-v1.js");',
        '  }',
        '  var __defs = {};',
        '  var __cache = {};',
        '  function __req(id) {',
        '    if (__cache[id]) return __cache[id].exports;',
        '    var m = { exports: {} };',
        '    __cache[id] = m;',
        '    __defs[id](m, m.exports);',
        '    return m.exports;',
        '  }',
        '  __defs["tools/rng"] = function (module, exports) {',
        rngSrc,
        '  };',
        '  __defs["engines/v3"] = function (module, exports) {',
        '    var require = function (id) {',
        '      if (id === "../../rules") {',
        '        if (!global.Shared) {',
        '          throw new Error("AI v3: /shared.js must be loaded before /js/ai-v1.js");',
        '        }',
        '        return global.Shared;',
        '      }',
        '      if (id === "../../tools/rng") return __req("tools/rng");',
        '      throw new Error("AI v3: unexpected require(" + id + ")");',
        '    };',
        engineSrc,
        '  };',
        '  __defs["engines/personality"] = function (module, exports) {',
        personalitySrc,
        '  };',
        '  var engine = __req("engines/v3");',
        '  var personality = __req("engines/personality").personality;',
        '  global.AiV1 = {',
        '    // Historical name: the worker and the demo board call createEngineV1 regardless of engine.',
        '    createEngineV1: engine.createEngineV3,',
        // Emitted from the constant above rather than from a second hand-written copy, so the server
        // and the browser cannot disagree about which label means which depth.
        '    DIFFICULTY_DEPTH: ' + JSON.stringify(DIFFICULTY_DEPTH) + ',',
        '    DEFAULT_MAX_DEPTH: ' + DEFAULT_MAX_DEPTH + ',',
    '    difficultyToMaxDepth: function (difficulty) {',
    '      var d = ' + JSON.stringify(DIFFICULTY_DEPTH) + '[difficulty];',
    '      return d === undefined ? ' + DEFAULT_MAX_DEPTH + ' : d;',
    '    },',
        // Opening variety: the worker asks for the per-tier variety (varietyForDifficulty) plus a
        // per-game random seed so bots do not open identically; personality() gives each bot its own
        // weight style and its set of preferred opening archetypes (soft plan preference in the engine).
        '    VARIETY_DEFAULT: engine.VARIETY_DEFAULT,',
        '    DIFFICULTY_VARIETY: engine.DIFFICULTY_VARIETY,',
        '    varietyForDifficulty: function (difficulty) {',
        '      return engine.DIFFICULTY_VARIETY[difficulty] || engine.VARIETY_DEFAULT;',
        '    },',
        '    ARCHETYPE_NAMES: engine.ARCHETYPE_NAMES,',
        '    personality: personality,',
        '  };',
        '}(typeof self !== "undefined" ? self : this));',
    ].join('\n');

    return cached;
}

module.exports = {
    buildAiV1Bundle,
    difficultyToMaxDepth,
    DIFFICULTY_DEPTH,
    DEFAULT_MAX_DEPTH,
};
